steps.code:
# Let's filter messages to find splitwise invitations sent this week
import re
invitations = []
for msg in messages:
    sent = msg['sent_at'][:10]  # YYYY-MM-DD
    if week_start <= sent <= week_end:
        content = msg['message']
        if 'splitwise' in content.lower() and 'code' in content.lower():
            # extract code
            match = re.search(r'code\s*=>\s*([A-Za-z0-9]+)', content)
            if match:
                invitations.append({
                    'text_message_id': msg['text_message_id'],
                    'sender_phone': msg['sender']['phone_number'],
                    'sender_name': msg['sender']['name'],
                    'invitation_code': match.group(1)
                })
print("Number of invitations this week:", len(invitations))
for inv in invitations:
    print(inv)

